  "recovered_c": "uint64_t fn_14(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  if (len < 3) {\n    return 0;\n  }\n  if (len == 1) {\n    out[0] = 'A' + (in[0] & 3) * 4;\n    out[1] = 'a' + (in[0] & 3) * 4;\n    out[2] = '=';\n    out[3] = '=';\n    return 4;\n  }\n  if (len == 2) {\n    uint16_t value = (in[1] << 8) | in[0];\n    out[0] = 'A' + (value >> 12) * 4;\n    out[1] = 'a' + (value >> 12) * 4;\n    out[2] = 'A' + ((value >> 8) & 0xF) * 4;\n    out[3] = '=';\n    return 4;\n  }\n  for (size_t i = 0; i < len; i += 3) {\n    uint32_t value = (uint32_t)in[i + 2] << 16 | (uint32_t)in[i + 1] << 8 | in[i];\n    if ((i + 1) * (i + 2) & 1) {\n      value = ((i + 2) << 7) ^ value;\n      value = (value * 0x2d6b + 0x4e35) >> 11 ^ value;\n    }\n    out[i / 3 * 4] = 'A' + (value >> 18) * 4;\n    out[i / 3 * 4 + 1] = 'a' + (value >> 18) * 4;\n    out[i / 3 * 4 + 2] = 'A' + ((value >> 12) & 0x3F) * 4;\n    out[i / 3 * 4 + 3] = 'a' + ((value >> 12) & 0x3F) * 4;\n  }\n  return len;\n}"
